import {createHash} from 'node:crypto';import * as T from '../../lib/three.module.min.js';
// Test-side geometry probe: real mesh vertices, including every wire instance.
export function meshReceipt(group){group.updateMatrixWorld(true);const points=[],p=new T.Vector3(),m=new T.Matrix4(),matrix=new T.Matrix4();group.traverse(o=>{if(!o.isMesh)return;const a=o.geometry.attributes.position,count=o.isInstancedMesh?o.count:1;for(let instance=0;instance<count;instance++){if(o.isInstancedMesh){o.getMatrixAt(instance,m);matrix.multiplyMatrices(o.matrixWorld,m);}else matrix.copy(o.matrixWorld);for(let i=0;i<a.count;i++){p.fromBufferAttribute(a,i).applyMatrix4(matrix);points.push([p.x,p.y,p.z].map(n=>(Math.abs(n)<.000005?0:n).toFixed(5)).join(','));}}});points.sort();return{vertices:points.length,sha256:createHash('sha256').update(points.join('\n')).digest('hex')};}
export function bounds(group){group.updateMatrixWorld(true);return new T.Box3().setFromObject(group);}
export function assertShift(assert,before,after,delta){assert(Number.isFinite(after.min.x),'moved assembly must contain real mesh geometry');for(const side of ['min','max'])for(const axis of ['x','y','z'])assert(Math.abs(after[side][axis]-before[side][axis]-delta[['x','y','z'].indexOf(axis)])<.00001,side+'.'+axis+' did not move with its assembly');}
